const frames = context.panel.data.series || [];

function valueFor(refId) {
  const frame = frames.find((item) => item.refId === refId);
  if (!frame) return null;
  const field = frame.fields.find((item) => item.name === "_value") ||
    frame.fields.find((item) => item.type === "number");
  if (!field || !field.values || field.values.length === 0) return null;
  const index = field.values.length - 1;
  const value = typeof field.values.get === "function"
    ? Number(field.values.get(index))
    : Number(field.values[index]);
  return Number.isFinite(value) ? value : null;
}

function variable(name, fallback) {
  const raw = context.grafana.replaceVariables("${" + name + "}");
  const value = Number(raw);
  return Number.isFinite(value) ? value : fallback;
}

const dailyPv = valueFor("A");
const peakPv = valueFor("B");
const loadL1Voltage = valueFor("C");
const loadL2Voltage = valueFor("I");
const loadVoltage = loadL1Voltage == null || loadL2Voltage == null ? null : loadL1Voltage + loadL2Voltage;
const batteryVoltage = valueFor("D");
const shuntBatterySoc = valueFor("E");
const solArkBatterySoc = valueFor("K");
const batterySoc = shuntBatterySoc == null ? solArkBatterySoc : shuntBatterySoc;
const batterySocTwoDecimals = batterySoc == null ? null : Math.round(batterySoc * 100) / 100;
const shuntAmpHours = valueFor("F");
const pvPower = valueFor("G") || 0;
const batteryPower = valueFor("H") || 0;

const solarThreshold = variable("solar_active_threshold_w", 100);
const batteryThreshold = variable("battery_active_threshold_w", 100);
const batteryCapacity = variable("battery_capacity_ah", 4012);
const calculatedAmpHours = batterySocTwoDecimals == null
  ? null
  : batteryCapacity * Math.max(0, 100 - batterySocTwoDecimals) / 100;
const ampHours = shuntAmpHours == null ? calculatedAmpHours : Math.abs(shuntAmpHours);

let inverterMode = "Standby";
if (batteryPower > batteryThreshold && pvPower > solarThreshold) inverterMode = "Battery + Solar";
else if (batteryPower > batteryThreshold) inverterMode = "Battery supply";
else if (pvPower > solarThreshold && batteryPower < -batteryThreshold) inverterMode = "Solar + charging";
else if (pvPower > solarThreshold) inverterMode = "Solar supply";
else if (batteryPower < -batteryThreshold) inverterMode = "Battery charging";

const day = new Intl.DateTimeFormat("en-US", { weekday: "short" }).format(new Date());
const energy = dailyPv == null ? "--" : dailyPv < 1 ? Math.round(dailyPv * 1000) + " Wh" : dailyPv.toFixed(1) + " kWh";
const peak = peakPv == null ? "0 W" : Math.abs(peakPv) >= 1000 ? (peakPv / 1000).toFixed(1) + " kW" : Math.round(peakPv) + " W";
const load = loadVoltage == null ? "--" : loadVoltage.toFixed(1) + " V";
const soc = batterySocTwoDecimals == null ? "--" : batterySocTwoDecimals.toFixed(2) + "%";
const volts = batteryVoltage == null ? "--" : batteryVoltage.toFixed(1) + " V";
const ah = ampHours == null ? "--" : ampHours.toFixed(0) + " Ah";

const width = context.panel.chart.getWidth();
const height = context.panel.chart.getHeight();
const pad = 10;
const gap = 8;
const tileW = (width - pad * 2 - gap * 5) / 6;
const tileH = height - pad * 2;
const tiles = [
  ["OPERATING MODE", inverterMode, "Live power-source logic", "#8AB8F2"],
  ["LOAD VOLTAGE", load, "L1 + L2", "#5794F2"],
  ["SOLAR TODAY", energy, day + " production", "#E5AC0E"],
  ["SOLAR PEAK", peak, "Today", "#E5AC0E"],
  ["BATTERY SOC", soc, volts, "#56A64B"],
  ["CHARGE NEEDED", ah, batteryCapacity.toFixed(0) + " Ah bank", "#FF9830"]
];

return {
  animationDurationUpdate: 250,
  backgroundColor: "transparent",
  graphic: tiles.flatMap((tile, index) => {
    const x = pad + index * (tileW + gap);
    return [
      {
        type: "rect",
        shape: { x, y: pad, width: tileW, height: tileH, r: 5 },
        style: { fill: "#1B1D21", stroke: "#34373D", lineWidth: 1 }
      },
      {
        type: "rect",
        shape: { x, y: pad, width: tileW, height: 4, r: [5, 5, 0, 0] },
        style: { fill: tile[3] }
      },
      {
        type: "text",
        style: { x: x + 12, y: pad + 18, text: tile[0], fill: "#9EA3AA", fontSize: 11, fontWeight: 700 }
      },
      {
        type: "text",
        style: { x: x + 12, y: pad + tileH / 2 + 2, text: tile[1], fill: "#F2F2F2", fontSize: 20, fontWeight: 700, verticalAlign: "middle" }
      },
      {
        type: "text",
        style: { x: x + 12, y: pad + tileH - 15, text: tile[2], fill: "#9EA3AA", fontSize: 11 }
      }
    ];
  })
};

const frame = context.panel.data.series?.[0];
if (!frame) return { title: { text: "No data", left: "center", top: "center" } };
const field = frame.fields.find((f) => f.name === "_value") || frame.fields.find((f) => f.type === "number");
if (!field || !field.values || field.values.length === 0) return { title: { text: "No data", left: "center", top: "center" } };
const index = field.values.length - 1;
const rawValue = Number(typeof field.values.get === "function" ? field.values.get(index) : field.values[index]);
const value = rawValue;
const parsedMax = Number(context.grafana.replaceVariables("${inverter_max_power_w}"));
const maxValue = Number.isFinite(parsedMax) && parsedMax > 0 ? parsedMax : 15000;
const width = context.panel.chart.getWidth();
const height = context.panel.chart.getHeight();
const left = 24;
const right = width - 24;
const barY = Math.round(height * 0.58);
const barH = 18;
const usable = right - left;
const magnitude = Math.min(Math.max(value, 0) / maxValue, 1) * usable;
const fillX = left;
const fillColor = "#5794F2";
const direction = Math.round(value) + " W";
return {
  backgroundColor: "transparent",
  graphic: [
    { type: "text", style: { x: left, y: 19, text: Math.round(value) + " W", fill: "#9EA3AA", fontSize: 12, fontWeight: 700 } },
    { type: "text", style: { x: right, y: 19, text: Math.round(Math.max(value,0) / maxValue * 100) + "% of scale", fill: "#F2F2F2", fontSize: 20, fontWeight: 700, align: "right" } },
    { type: "rect", shape: { x: left, y: barY, width: usable, height: barH, r: 9 }, style: { fill: "#35383E" } },
    { type: "rect", shape: { x: fillX, y: barY, width: magnitude, height: barH, r: 9 }, style: { fill: fillColor } },

    { type: "text", style: { x: left, y: height - 16, text: "0 W", fill: "#777B82", fontSize: 10 } },
    { type: "text", style: { x: right, y: height - 16, text: maxValue + " W", fill: "#777B82", fontSize: 10, align: "right" } }
  ]
};

